from main import handle

assert handle({'command': 'quote', 'line': {
    'line_id': 'L', 'account_id': 'A', 'subscription_id': 'S',
    'service_on': '2020-01-01', 'charge_cents': 19999,
}}) == {
    'release': '2.0', 'line_id': 'L', 'credit_cents': 2999,
    'amount_due_cents': 17000,
}

lines = [
    {'line_id': 'z', 'account_id': 'A', 'subscription_id': 'S1', 'service_on': '2026-01-03', 'charge_cents': 10000},
    {'line_id': 'a', 'account_id': 'A', 'subscription_id': 'S2', 'service_on': '2026-01-02', 'charge_cents': 10000},
    {'line_id': 'b', 'account_id': 'B', 'subscription_id': 'S1', 'service_on': '2026-01-01', 'charge_cents': 10000},
]
assert handle({'command': 'total', 'lines': lines}) == {
    'release': '2.0', 'credit_cents': 6000, 'amount_due_cents': 24000,
}
# Equal charges use line_id order: a gets the full cap, z gets zero.
assert handle({'command': 'total', 'release': '2.0', 'lines': lines[:2]}) == {
    'release': '2.0', 'credit_cents': 3000, 'amount_due_cents': 17000,
}
legacy = [
    {'line_id': 'later', 'account_id': 'A', 'subscription_id': 'S', 'service_on': '2026-02-01', 'charge_cents': 20000},
    {'line_id': 'earlier', 'account_id': 'A', 'subscription_id': 'S', 'service_on': '2026-01-01', 'charge_cents': 20000},
]
assert handle({'command': 'total', 'release': '1.0', 'lines': legacy}) == {
    'release': '1.0', 'credit_cents': 2400, 'amount_due_cents': 37600,
}
print('targeted release checks passed')
